def word_count(text: str) -> dict:
    words = text.split()
    cleaned_words = []
    for word in words:
        stripped = word.strip('.,!?
	')
        if stripped:
            cleaned_words.append(stripped.lower())
    return dict.fromkeys(cleaned_words, 0) or {word: cleaned_words.count(word) for word in cleaned_words}

def merge_intervals(iv: list) -> list:
    if not iv:
        return []

    # Sort intervals based on start time
    iv.sort()

    merged = [iv[0]]

    for current in iv[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # Overlapping intervals, merge them
            merged[-1] = [last[0], max(last[1], current[1])]
        else:
            merged.append(current)

    return merged

def c_to_f(c: float) -> float:
    f = c * 9 / 5 + 32
    return round(f, 1)

def roman_to_int(s: str) -> int:
    roman = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev_value = 0
    for char in reversed(s):
        value = roman[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total

def median(nums: list) -> float:
    nums_sorted = sorted(nums)
    n = len(nums_sorted)
    if n % 2 == 1:
        return float(nums_sorted[n // 2])
    else:
        return (nums_sorted[n // 2 - 1] + nums_sorted[n // 2]) / 2.0

def dedupe(xs: list) -> list:
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def fizzbuzz(n: int) -> list:
    result = []
    for i in range(1, n + 1):
        s = ''
        if i % 3 == 0:
            s += 'Fizz'
        if i % 5 == 0:
            s += 'Buzz'
        result.append(s or str(i))
    return result

